/* Panda Passport service worker: precaches the whole app (including the recorded audio) so it works offline. Generated by tools/build_sw.py. */
const CACHE = 'panda-passport-__VERSION__';
const FILES = [
  __FILES__
];
/* Recorded Mandarin clips: cached during install too, but best effort (a failed clip is fetched again on first play). */
const AUDIO = [
  __AUDIO__
];
async function cacheAudio(c) {
  const have = new Set((await c.keys()).map(r => new URL(r.url).pathname.split('/').pop()));
  const todo = AUDIO.filter(f => !have.has(f.split('/').pop()));
  // Clip names change whenever their audio changes, so a clip from an older cache can be reused as is.
  for (let i = 0; i < todo.length; i += 24) await Promise.all(todo.slice(i, i + 24).map(f =>
    caches.match(f, { ignoreSearch: true }).then(old => old ? c.put(f, old) : c.add(f)).catch(() => {})));
}
self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES).then(() => cacheAudio(c))).then(() => self.skipWaiting()));
});
self.addEventListener('message', e => {
  if (e.data === 'cache-audio') e.waitUntil(caches.open(CACHE).then(cacheAudio).then(() => e.source && e.source.postMessage('audio-cached')));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith('panda-passport-') && k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});
/* Safari asks for media with Range headers; answer those from the cache with a proper 206. */
async function partial(req, res) {
  const m = /bytes=(\d*)-(\d*)/.exec(req.headers.get('range') || '');
  if (!m || !res || res.status !== 200) return res;
  const buf = await res.arrayBuffer(), size = buf.byteLength;
  let start = m[1] ? +m[1] : 0, end = m[2] ? +m[2] : size - 1;
  if (!m[1] && m[2]) { start = Math.max(0, size - +m[2]); end = size - 1; }
  end = Math.min(end, size - 1);
  if (start >= size || start > end) return new Response(null, { status: 416, headers: { 'Content-Range': 'bytes */' + size } });
  return new Response(buf.slice(start, end + 1), { status: 206, statusText: 'Partial Content', headers: {
    'Content-Type': res.headers.get('Content-Type') || 'audio/mpeg', 'Content-Range': 'bytes ' + start + '-' + end + '/' + size,
    'Content-Length': String(end - start + 1), 'Accept-Ranges': 'bytes' } });
}
self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  if (req.headers.has('range')) {
    e.respondWith(caches.match(req.url, { ignoreSearch: true }).then(hit => hit ? partial(req, hit)
      : fetch(req.url).then(res => {
        if (res.status !== 200) return fetch(req);
        caches.open(CACHE).then(c => c.put(req.url, res.clone())).catch(() => {});
        return partial(req, res.clone());
      }).catch(() => fetch(req))));
    return;
  }
  e.respondWith(
    caches.match(req, { ignoreSearch: true }).then(hit => hit || fetch(req).then(res => {
      if (res.status === 200 && res.type === 'basic') { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)).catch(() => {}); }
      return res;
    }).catch(() => req.mode === 'navigate' ? caches.match('./') : Response.error()))
  );
});
